    "    col = mix( col, mix( max( col, 0.0), pow( abs( f.xyz ), vec3( 1.4 ) ) * fvig, f.w * f.w), vec3( use_frame ) );\n"
    "\n"
    "    FragColor = vec4( col, 1.0 );\n"
    "}\n"
    "\n";
